class LRUCache:
    """
    A class representing an LRU (Least Recently Used) Cache
    using a hash map for O(1) access and a circular queue
    for maintaining the order of usage.
    """
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.head = -1  # Points to the least recently used item
        self.queue = []  # Circular queue to track usage order

    def _update_queue(self, key: int) -> None:
        if key in self.queue:
            self.queue.remove(key)
        if len(self.queue) == self.capacity:
            lru_key = self.queue.pop(0)
            del self.cache[lru_key]
        self.queue.append(key)

    def get(self, key: int) -> int:
        if key in self.cache:
            self._update_queue(key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        self.cache[key] = value
        self._update_queue(key)

class LRUCache:
    """
    A class representing an LRU (Least Recently Used) Cache
    using a combination of a dictionary for O(1) access 
    and a list to maintain the order of keys.
    """
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.order = []

    def get(self, key: int) -> int:
        if key in self.cache:
            # Move the accessed key to the end to mark it as recently used
            self.order.remove(key)
            self.order.append(key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache[key] = value
            self.order.remove(key)
            self.order.append(key)
        else:
            if len(self.cache) >= self.capacity:
                # Remove the least recently used key
                lru_key = self.order.pop(0)
                del self.cache[lru_key]
            # Insert the new key-value pair
            self.cache[key] = value
            self.order.append(key)
